extern alias ActualCore;
using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections;using System.Collections.Generic;using Newtonsoft.Json.Linq;using Game.Components;using Game.Configs;using Unity.Entities;
namespace Game.Runtime{
 internal sealed class GeneratedBuildingDefinitions{
 internal readonly List<RuntimeDefinition> Definitions=new List<RuntimeDefinition>();
 internal readonly Dictionary<string,JObject> AssetIdentities=new Dictionary<string,JObject>(StringComparer.Ordinal);
 internal readonly Dictionary<string,SourceUnitPrefab> Assets=new Dictionary<string,SourceUnitPrefab>(StringComparer.Ordinal);
 internal readonly Dictionary<string,JObject> PresentationAssetBindings=new Dictionary<string,JObject>(StringComparer.Ordinal);
 private readonly ExactInitialValueCodec codec;private readonly IDictionary<string,Entity> templates;
 static readonly HashSet<string> PresentationOnly=new HashSet<string>(StringComparer.Ordinal){"DestroyedVisualPrefab","SelectionPortraitSprite","CardPortraitSprite","AttackImpactPrefab","MuzzleFlashPrefab","VisualTemplate","GeneratedMeshes"};
 GeneratedBuildingDefinitions(string directory,IDictionary<string,Entity> sourceTemplates){codec=new ExactInitialValueCodec(directory,new JObject());templates=sourceTemplates;}
 internal static GeneratedBuildingDefinitions Load(string path,string sha,uint expectedSetup,IDictionary<string,Entity> templates){var bytes=AutonomousWorld.PinnedFile(path,sha,4*1024*1024);var j=JObject.Parse(System.Text.Encoding.UTF8.GetString(bytes),new JsonLoadSettings{DuplicatePropertyNameHandling=DuplicatePropertyNameHandling.Error});if((int?)j["schema_version"]!=1||(uint?)j["setup_hash"]!=expectedSetup||(j["unsupported_values"]as JArray)?.Count!=0)throw new InvalidDataException("Actual setup-bound complete definition export required");var rows=j["definitions"]as JArray;if(rows==null||rows.Count!=8)throw new InvalidDataException("Actual eight S002 definitions required");var r=new GeneratedBuildingDefinitions(Path.GetDirectoryName(path),templates);foreach(JObject row in rows){var key=(string)row["key"];var fields=row["fields"]as JObject;if(string.IsNullOrEmpty(key)||fields==null)throw new InvalidDataException("Definition fields/key required");var d=new RuntimeDefinition();foreach(var field in typeof(RuntimeDefinition).GetFields(BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic)){if(field.Name=="SourceMetadataComplete")continue;if(!fields.TryGetValue(field.Name,out var v))throw new InvalidDataException("Missing actual definition field "+field.Name);if(PresentationOnly.Contains(field.Name)){r.PresentationAssetBindings[key+"/"+field.Name]=(JObject)v.DeepClone();continue;}try{field.SetValue(d,r.Decode(v,field.FieldType,key+"/"+field.Name));}catch(Exception error){throw new InvalidDataException("Exact building field decode failed: "+key+"/"+field.Name,error);}}foreach(var name in PresentationOnly)if(fields[name]!=null)r.PresentationAssetBindings[key+"/"+name]=(JObject)fields[name].DeepClone();if(d.Prefab==null||d.Prefab.name!=key||d.HasRunway||d.IsWall)throw new NotSupportedException("Complete ordinary ground definition required");d.SourceMetadataComplete=true;r.Definitions.Add(d);}if(r.Definitions.Select(x=>x.Prefab.name).Distinct(StringComparer.Ordinal).Count()!=8)throw new InvalidDataException("Unique definition identities required");return r;}
 object Decode(JToken token,Type expected,string path){var codecName=(string)token["codec"];if(codecName=="source-asset-reference-v1"){if(expected!=typeof(SourceUnitPrefab))throw new NotSupportedException("Asset reference requires logical source token at "+path);string key=(string)token["key"],assetPath=(string)token["path"],guid=(string)token["guid"];long id=(long)token["local_id"];if(string.IsNullOrEmpty(key)||string.IsNullOrEmpty(assetPath)||guid?.Length!=32||id==0)throw new InvalidDataException("Complete actual asset identity required");var checkedIdentity=SourceUnitPrefab.FromAssetIdentity(key,assetPath,guid,id);if(AssetIdentities.TryGetValue(key,out var existingIdentity)&&!JToken.DeepEquals(existingIdentity,token))throw new InvalidDataException("Conflicting R6 source asset identity "+key);AssetIdentities[key]=(JObject)token.DeepClone();if(Assets.TryGetValue(key,out var prior))return prior;var result=templates.TryGetValue(key,out var template)?new SourceUnitPrefab(key,template):SourceUnitPrefab.FromAssetIdentity(key,assetPath,guid,id);Assets.Add(key,result);return result;}
 if(codecName=="definition-list-v1"){var rows=token["items"]as JArray;if(rows==null||rows.Count>4096)throw new InvalidDataException("Bounded definition list required");Type element=expected.IsArray?expected.GetElementType():expected.GetGenericArguments().Single();var a=Array.CreateInstance(element,rows.Count);for(int i=0;i<rows.Count;i++)a.SetValue(Decode(rows[i],element,path+"/"+i),i);if(expected.IsArray)return a;var list=(IList)Activator.CreateInstance(expected);foreach(var value in a)list.Add(value);return list;}
 if(codecName=="definition-fields-v1"){var value=Activator.CreateInstance(expected);var fields=(JObject)token["fields"];foreach(var f in expected.GetFields(BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic)){if(fields[f.Name]==null)throw new InvalidDataException("Missing exact slot field");f.SetValue(value,Decode(fields[f.Name],f.FieldType,path+"/"+f.Name));}return value;}return codec.Decode(token,expected,path);}
 }
 internal sealed partial class RuntimeDefinition{internal int RefugeeCapacity;internal int RefugeeUpkeepPerCitizenPerDay;internal ActualCore::UnityEngine.Quaternion RunwayLocalRotation;}
}
